def parse_closes(text):
    rows = text.splitlines()[1:]
    return [float(row.split(",")[1]) for row in rows]


def total_return(closes):
    return closes[-1] / closes[0] - 1


def format_return(r):
    return f"Return: {r:.2%}"


def report(text):
    print(format_return(total_return(parse_closes(text))))


report("date,close\n2026-10-12,100.00\n2026-10-13,104.00\n")

